graph {
    node ExternalSource browser_input {
        size 3;
        channels 1;
        initial 0;
    }

    node ConsoleSink console {
        max_channels 3;
        fps 2;
        connect browser_input;
    }
}

# RASL Virtual Source/Sink Configuration
# Sawtooth-driven rainbow with TwinkleEffect transform

ui {
    port 8080;
}

graph {
    # ─────────────────────────────────────────────────────────────────
    # COLOR GENERATION PIPELINE
    # Sawtooth wave drives hue for uniform rainbow cycling
    # Using OkHSL for perceptually uniform hue distribution
    # ─────────────────────────────────────────────────────────────────

    # Sawtooth wave for uniform hue cycling (rainbow effect)
    # Unlike sine, sawtooth gives equal time to each hue
    node Waveform hue_ramp {
        shape sine;
        frequency_hz 0.01;
        output_channels 150;
        fps 30;
    }

    node literal xmas_light_colors color:hsl [
        [0, 1, 0.5],
        [0.04, 1, 0.5],
        #[0.16, 1, 0.5],
        [0.35, 1, 0.5],
        [0.64, 1, 0.5],
    ];

    node SacnSource hyperhdr {
        bind_port 5568;
        universes 1;
    }

  node Color hyperhdr_color srgb {
        connect hyperhdr universe1;
    }


    # node ConsoleSink console_hyperhdr {
    #     max_channels 24;
    #     include_metadata true;
    #     fps 1;

    #     connect hyperhdr;
    # }



#     node ConsoleSink hypderhdr_debug {
#         connect hyperhdr;
#         fps 1;
#     }

    node literal pure_white color:srgb [[1, 1, 1]];

    # Compose into OkHSL color (hue, saturation, lightness)
    # OkHSL provides perceptually uniform hue distribution
    # NOTE: S=0.7, L=0.6 gives most uniform brightness across hues
    # S=1.0, L=0.5 has a dark spot at blue-purple (h≈0.74) due to gamut limits
    node Compose hsl {
        ports {
            hue; saturation; lightness;
        }
        output_type hsl;
        #output_channels 512;  # Required when all ports use fill

        connect hue_ramp hue;
        fill saturation 1;
        fill lightness 0.5;
    }

    node Color hsl_rgb rgb {
        connect hsl {
            repeat 30;
        }
    }

    node Color rgb_150 rgb {
        connect hsl_rgb {
            repeat 30;
        }
    }

#     node ConsoleSink hsl_console {
#         connect hsl_rgb[0:1];
#         fps 1;
#     }

    # ─────────────────────────────────────────────────────────────────
    # TWINKLE EFFECT (transform)
    # Modulates brightness of incoming color
    # ─────────────────────────────────────────────────────────────────

    # TwinkleEffect modes:
    # - brightness: fade to black (classic twinkle) [default]
    # - whiteness: fade to white (sparkle)
    node TwinkleEffect twinkle {
        seed 11337;
        mode brightness;
        frequency_hz 0.3;
        attack_ratio 0.33;
        min_speed 1.0;
        max_speed 3.0;

        connect rgb_150;
    }

    node Color white_150 rgb {
        connect pure_white {
            repeat 120;
        }
    }

    node TwinkleEffect white_twinkle {
        seed 11337;
        mode brightness;
        frequency_hz 0.3;
        attack_ratio 0.33;
        min_speed 1.0;
        max_speed 3.0;

        connect white_150;
    }

    node cron minute_selector {
        schedule "*/2 * * * *";
    }

    node Crossfade minute_crossfade {
        connect twinkle input0;
        connect white_twinkle input1;
        connect minute_selector selector;
    }

    node Color crossfade_rgb rgb {
        connect minute_crossfade;
    }

    # Convert sRGB to linear RGB for color correction
    # sACN outputs 512 DMX channels, slice to 432 (144 RGB pixels)
    # node Color toRgb linear {
    #     connect hyperhdr[0:432];
    # }

    # ─────────────────────────────────────────────────────────────────
    # COLOR CORRECTION PROFILES
    # Apply per-LED-type corrections for better saturation and color
    # ─────────────────────────────────────────────────────────────────

    # Profile A: Ray Wu 12V WS2811 Bullet Pixels (good color accuracy)
    # node ColorCorrection profile_a {
    #     gamma 2.0;           # Close to sRGB curve, not too aggressive
    #     saturation 1.1;      # Small boost; bullets already show color well
    #     brightness 1.0;

    #     r_scale 1.0;         # Neutral white balance
    #     g_scale 1.0;
    #     b_scale 1.0;

    #     connect toRgb;
    # }

    # # Profile B: Ray Wu 12V WS2811 Icicle Pixels (washed-out lows)
    # node ColorCorrection profile_b {
    #     gamma 1.2;           # LOWER gamma: preserves dark colors, fixes purple→white washout
    #     saturation 1.25;     # A bit more saturation to counter low-end smearing
    #     brightness 0.8;

    #     r_scale 1.00;        # Slight green reduction, slight blue boost
    #     g_scale 0.96;        # icicles often lean green/teal in the lows
    #     b_scale 1.05;

    #     connect toRgb;
    # }

    # ─────────────────────────────────────────────────────────────────
    # OUTPUT SINKS
    # ─────────────────────────────────────────────────────────────────

    node ConsoleSink console {
        max_channels 24;
        as_bytes true;
        fps 1;

        connect crossfade_rgb;
    }

    # DDP sink with per-LED-type color correction
    # First 50 pixels use profile_a, next 200 pixels use profile_b
    node DdpSink leds {
        target "10.0.60.30";
        fps 20hz;
        input_port pixels;
        max_count 2284;

        # 2284 total pixels

        # # First 50 pixels from profile_a
        connect crossfade_rgb pixels {
            repeat_until 2284;
        }

        # connect hsl_rgb[0:100] pixels {
        #         repeat 20;
        # }
    }
}

# RASL Virtual Source/Sink Configuration
# Sawtooth-driven rainbow with TwinkleEffect transform

graph {
    # produces 149 channels
    # group 0 is 144 channels of 16x9 = 432 bytes
    # group 1 is 4 channels of 2x2 = 12 bytes
    # group 2 is 1 channel of 1x1 = 3 bytes

    node SacnSource hyperhdr {
        bind_port 5568;

        universe 1 {
            channels 144;  # 16x9
        }

        universe 2 {
            channels 8; # 2x4
        }
    }

    node Color hyperhdr_color rec709_rgb_prime {
        connect hyperhdr.channels;
    }

    node ConsoleSink u2_raw_console {
        fps 1;
        as_bytes true;
        connect hyperhdr_color[144:152];
    }

    node ConsoleSink u2_range_console {
        fps 1;
        as_bytes true;
        connect hyperhdr_range_map[144:152];
    }

    node ConsoleSink hyperhdr_console {
        connect hyperhdr_color;
        fps 1;
    }

    node RangeMap hyperhdr_range_map {
        ranges 0.0627 0.922;
        ranges 0.0627 0.922;
        ranges 0.0627 0.922;
        clamp true;

        connect hyperhdr_color;
    }

    node MatrixMultiply hyperhdr_matrix {
        matrix 0.96409927 0.02731212 0.00858861;
        matrix 0.00451189 1.01313961 -0.01765150;
        matrix 0.00899431 0.01377757 0.97722811;

        connect hyperhdr_range_map;
    }

    node Smooth hyperhdr_smooth {
        connect hyperhdr_matrix input;
        smooth_period 200ms;
    }

    node Color rec709_to_rgb rgb {
        connect hyperhdr_smooth;
    }

    node Color rec709_to_srgb srgb {
        connect hyperhdr_smooth;
    }

    node ConsoleSink console {
        max_channels 24;
        as_bytes true;
        fps 1;

        connect rec709_to_rgb;
    }

    node RandomMap leds_random_map {
        channel_count 2284;
        seed 424242;

        # ddp pixels (sACN universe 1)
        connect rec709_to_rgb[0:144];
    }

    node DdpSink leds {
        target "10.0.60.30";
        fps 20hz;
        input_port pixels;
        max_count 2284;

        connect leds_random_map pixels;
    }

    node MatrixMultiply lifx_rgb_dim {
        matrix 0.3 0 0;
        matrix 0 0.3 0;
        matrix 0 0 0.3;

        connect rec709_to_rgb[144:152];
    }

    node Color lifx_dimmed_rgb rgb {
        connect lifx_rgb_dim;
    }

